n = int(input())
parked = {}
total = 0
for _ in range(n):
    t, car, kind = input().split()
    now = int(t[:2]) * 60 + int(t[3:])
    if kind == "IN":
        if car in parked:
            print("기록 오류")
        else:
            parked[car] = now
    else:
        if car not in parked:
            print("기록 오류")
        else:
            m = now - parked[car]
            del parked[car]
            fee = 0
            if m > 30:
                over = m - 30
                fee = (over // 10) * 300
                if over % 10 != 0:
                    fee += 300
            if fee > 5000:
                fee = 5000
            total += fee
            print(f"{car} {m}분 {fee}원")
print(f"총 요금 {total}원")
